1402	+import { DOCUMENT } from '@angular/common';
1403	+import { inject, Injectable } from '@angular/core';
1404	+
1405	+export const PLAY_BILLING_METHOD = 'https://play.google.com/billing';
1406	+
1407	+/** A tip product as the Play Store sells it in the player's country. */
1408	+export interface TipProduct {
1409	+  readonly id: string;
1410	+  readonly title: string;
1411	+  readonly price: string;
1412	+}
1413	+
1414	+export type TipOutcome = 'purchased' | 'cancelled';
1415	+
1416	+interface DigitalGoodsItem {
1417	+  readonly itemId: string;
1418	+  readonly title: string;
1419	+  readonly price: { readonly currency: string; readonly value: string };
1420	+}
1421	+
1422	+interface DigitalGoodsPurchase {
1423	+  readonly itemId: string;
1424	+  readonly purchaseToken: string;
1425	+}
1426	+
1427	+/** The part of the Digital Goods API the app's billing bridge answers. */
1428	+export interface DigitalGoodsService {
1429	+  getDetails(itemIds: string[]): Promise<DigitalGoodsItem[]>;
1430	+  listPurchases(): Promise<DigitalGoodsPurchase[]>;
1431	+  consume(purchaseToken: string): Promise<void>;
1432	+}
1433	+
1434	+export type DigitalGoodsWindow = Window & {
1435	+  getDigitalGoodsService?: (method: string) => Promise<DigitalGoodsService>;
1436	+};
1437	+
1438	+/**
1439	+ * Tips inside the Play Store app, sold as consumable Play products through
1440	+ * the Digital Goods API and Payment Request.
1441	+ *
1442	+ * A tip unlocks nothing, so no server checks the purchase: consuming it
1443	+ * acknowledges it (Play refunds a purchase nobody acknowledged after three
1444	+ * days) and makes the product buyable again.
1445	+ */
1446	+@Injectable({ providedIn: 'root' })
1447	+export class PlayBillingService {
1448	+  private readonly window = inject(DOCUMENT)
1449	+    .defaultView as DigitalGoodsWindow | null;
1450	+  private service: Promise<DigitalGoodsService | null> | null = null;
1451	+
1452	+  /** The products in the given order, or null without Play Billing. */
1453	+  public async loadProducts(
1454	+    ids: readonly string[]
1455	+  ): Promise<TipProduct[] | null> {
1456	+    const service = await this.digitalGoods();
1457	+    if (!service) return null;
1458	+    try {
1459	+      const items = await service.getDetails([...ids]);
1460	+      const byId = new Map(items.map((item) => [item.itemId, item]));
1461	+      return ids.flatMap((id) => {
1462	+        const item = byId.get(id);
1463	+        return item
1464	+          ? [{ id, title: item.title, price: formatPrice(item.price) }]
1465	+          : [];
1466	+      });
1467	+    } catch {
1468	+      return null;
1469	+    }
1470	+  }
1471	+
1472	+  public async buy(productId: string): Promise<TipOutcome> {
1473	+    const service = await this.digitalGoods();
1474	+    if (!service || typeof PaymentRequest === 'undefined') {
1475	+      throw new Error('Play Billing is not available');
1476	+    }
1477	+    const request = new PaymentRequest(
1478	+      [{ supportedMethods: PLAY_BILLING_METHOD, data: { sku: productId } }],
1479	+      { total: { label: 'Total', amount: { currency: 'EUR', value: '0' } } }
1480	+    );
1481	+    let response: PaymentResponse;
1482	+    try {
1483	+      response = await request.show();
1484	+    } catch (err) {
1485	+      if (err instanceof DOMException && err.name === 'AbortError') {
1486	+        return 'cancelled';
1487	+      }
1488	+      throw err;
1489	+    }
1490	+    const purchaseToken = (
1491	+      response.details as { purchaseToken?: unknown } | undefined
1492	+    )?.purchaseToken;
1493	+    // The player has paid by now, so a failed consume is no failure to
1494	+    // them: `consumePending` on the next start acknowledges the purchase,
1495	+    // well inside Play's three days.
1496	+    if (typeof purchaseToken === 'string' && purchaseToken) {
1497	+      await service.consume(purchaseToken).catch(() => undefined);
1498	+    }
1499	+    await response.complete('success').catch(() => undefined);
1500	+    return 'purchased';
1501	+  }
1502	+
1503	+  /**
1504	+   * Consumes the tips an app closed too early left unconsumed, so Play
1505	+   * neither refunds them nor refuses to sell the same tip again. Other
1506	+   * products are left alone.
1507	+   */
1508	+  public async consumePending(tipProductIds: readonly string[]): Promise<void> {
1509	+    const service = await this.digitalGoods();
1510	+    if (!service) return;
1511	+    try {
1512	+      const purchases = await service.listPurchases();
1513	+      await Promise.allSettled(
1514	+        purchases
1515	+          .filter((purchase) => tipProductIds.includes(purchase.itemId))
1516	+          .map((purchase) => service.consume(purchase.purchaseToken))
1517	+      );
1518	+    } catch {
1519	+      // Tried again on the next start.
1520	+    }
1521	+  }
1522	+
1523	+  private digitalGoods(): Promise<DigitalGoodsService | null> {
1524	+    const pending = (this.service ??= this.connect());
1525	+    // A failed connect - the app's bridge not bound yet - is tried again on
1526	+    // the next call rather than turning billing off for the session.
1527	+    void pending.then((service) => {
1528	+      if (!service && this.service === pending) this.service = null;
1529	+    });
1530	+    return pending;
1531	+  }
1532	+
1533	+  private async connect(): Promise<DigitalGoodsService | null> {
1534	+    const connect = this.window?.getDigitalGoodsService;
1535	+    if (typeof connect !== 'function') return null;
1536	+    try {
1537	+      return await connect.call(this.window, PLAY_BILLING_METHOD);
1538	+    } catch {
1539	+      return null;
1540	+    }
1541	+  }
1542	+}
1543	+
1544	+function formatPrice(price: DigitalGoodsItem['price']): string {
1545	+  try {
1546	+    return new Intl.NumberFormat(undefined, {
1547	+      style: 'currency',
1548	+      currency: price.currency,
1549	+    }).format(Number(price.value));
1550	+  } catch {
1551	+    return `${price.value} ${price.currency}`;
1552	+  }
1553	+}
