1704	+const TWA_SESSION_KEY = 'bacteria-game.twa';
1705	+
1706	+/**
1707	+ * The `source` the Play Store app's launch URL carries (`build.gradle.kts`):
1708	+ * the WebView fallback sends no referrer, and other apps' referrers say
1709	+ * nothing about this one.
1710	+ */
1711	+export const APP_LAUNCH_SOURCE = 'twa';
1712	+
1713	+/**
1714	+ * Whether the game runs inside the Play Store app with the given package:
1715	+ * launched with `?source=twa`, or opened from a link by Chrome, which
1716	+ * then sends the referrer `android-app://<package>`. A reload inside the app
1717	+ * loses both, hence the flag in the session storage.
1718	+ */
1719	+export function isTwaSession(document: Document, appPackage: string): boolean {
1720	+  const storage = document.defaultView?.sessionStorage;
1721	+  const source = new URLSearchParams(document.location.search).get('source');
1722	+  const referrer = document.referrer.replace(/\/$/, '');
1723	+  if (
1724	+    source === APP_LAUNCH_SOURCE ||
1725	+    referrer === `android-app://${appPackage}`
1726	+  ) {
1727	+    try {
1728	+      storage?.setItem(TWA_SESSION_KEY, '1');
1729	+    } catch {
1730	+      // Storage blocked: the referrer or the query still covers this page load.
1731	+    }
1732	+    return true;
1733	+  }
1734	+  try {
1735	+    return storage?.getItem(TWA_SESSION_KEY) === '1';
1736	+  } catch {
1737	+    return false;
1738	+  }
1739	+}

